//! The Rust OCI config against Python's `DirectOciConfigBuilder.build` for
//! representative specs (semantic equality), and `rootfs::json_indent2`
//! against Python's `json.dumps(config, indent=2, sort_keys=True)` byte for byte.
//!
//! GOLDEN is the output of GENERATOR (below) run with the repository's Python;
//! `cargo test --test oci_golden -- --ignored` re-runs it and compares.

use std::path::{Path, PathBuf};

use serde_json::Value;
use ucloud_noded::image::{EnvironmentManifest, HOST_EROFS_ABI, ImageConfig, MaterializedRootfs};
use ucloud_noded::oci::{NetworkMode, OciBuilder, SandboxSpec, validate_init_binary};
use ucloud_noded::rootfs::json_indent2;

/// A root-owned, executable host binary nobody else may write (the init fixture).
fn trusted_binary() -> PathBuf {
    ["/bin/true", "/usr/bin/true", "/bin/sh", "/usr/bin/env"]
        .iter()
        .map(PathBuf::from)
        .find(|path| validate_init_binary(path).is_ok())
        .expect("a root-owned host binary for the init fixtures")
}

fn scratch(name: &str) -> PathBuf {
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos();
    let root = std::env::temp_dir().join(format!("noded-oci-{name}-{}-{nanos}", std::process::id()));
    std::fs::create_dir_all(root.join("rootfs/etc")).unwrap();
    root
}

fn image(rootfs: &Path, config: &Value) -> MaterializedRootfs {
    MaterializedRootfs {
        image_ref: "registry.example:5000/env:task".into(),
        image_id: format!("sha256:{}", "a".repeat(64)),
        rootfs_identity_sha256: "b".repeat(64),
        rootfs: rootfs.to_path_buf(),
        image_config: ImageConfig::from_inspection(config).unwrap(),
        environment: EnvironmentManifest { base: format!("sha256:{}", "a".repeat(64)), workspace: None, toolkits: vec![] },
        backend_abi: HOST_EROFS_ABI,
    }
}

fn check(golden: &Value) {
    let root = scratch("golden");
    let rootfs = root.join("rootfs");
    std::fs::write(rootfs.join("etc/passwd"), golden["passwd"].as_str().unwrap()).unwrap();
    std::fs::write(rootfs.join("etc/group"), golden["group"].as_str().unwrap()).unwrap();
    let init = trusted_binary();
    let cases = golden["cases"].as_array().unwrap();
    assert!(cases.len() > 30);
    let mut texts = 0;
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let mode = if case["network_mode"] == "sandbox" { NetworkMode::Sandbox } else { NetworkMode::None };
        let builder = OciBuilder::new(Some(init.clone()), Some(init.clone()), mode).unwrap();
        let netns = case["netns"].as_str().map(PathBuf::from);
        let result = SandboxSpec::from_value(&case["spec"])
            .and_then(|spec| builder.build(&spec, &image(&rootfs, &case["image_config"]), netns.as_deref()));
        match (case.get("config"), result) {
            (Some(expected), Ok(config)) => {
                assert_eq!(&config, expected, "{name}");
                if let Some(text) = case.get("config_text") {
                    assert_eq!(json_indent2(&config) + "\n", text.as_str().unwrap(), "{name}");
                    texts += 1;
                }
            }
            (None, Err(error)) => assert_eq!(error.to_string(), case["error"].as_str().unwrap(), "{name}"),
            (expected, actual) => panic!("{name}: expected {expected:?} or {:?}, got {actual:?}", case.get("error")),
        }
    }
    assert_eq!(texts, 3);
    std::fs::remove_dir_all(&root).unwrap();
}

#[test]
fn configs_match_the_python_builder() {
    check(&serde_json::from_str(GOLDEN).unwrap());
}

/// Regenerate with the repository's Python and compare (needs `.venv`).
#[test]
#[ignore]
fn golden_is_what_python_generates_now() {
    let repository = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let root = scratch("generator");
    std::fs::write(root.join("golden.py"), GENERATOR).unwrap();
    let output = std::process::Command::new(repository.join(".venv/bin/python"))
        .arg(root.join("golden.py"))
        .arg(trusted_binary())
        .current_dir(&repository)
        .output()
        .unwrap();
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    let fresh: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(fresh, serde_json::from_str::<Value>(GOLDEN).unwrap());
    check(&fresh);
    std::fs::remove_dir_all(&root).unwrap();
}

#[tokio::test]
async fn the_static_helper_must_answer_its_probe() {
    let shell = SandboxSpec::from_value(&serde_json::json!({"id": "s", "image": "i", "memory_mb": 1, "disk_mb": 1})).unwrap();
    let static_helper = SandboxSpec::from_value(&serde_json::json!({
        "id": "s", "image": "i", "memory_mb": 1, "disk_mb": 1, "filesystem": {"management_helper": "static"}}))
    .unwrap();
    let none = OciBuilder::new(None, None, NetworkMode::Sandbox).unwrap();
    none.validate_management_helper(&shell).await.unwrap();
    assert_eq!(
        none.validate_management_helper(&static_helper).await.unwrap_err().to_string(),
        "static file management requires an updated managed-process binary"
    );
    let init = trusted_binary();
    let builder = OciBuilder::new(None, Some(init.clone()), NetworkMode::Sandbox).unwrap();
    let probed = builder.validate_management_helper(&static_helper).await;
    if init.file_name().unwrap() == "true" {
        probed.unwrap();
    }
    assert!(OciBuilder::new(Some("relative".into()), None, NetworkMode::None).is_err());
}

