const GENERATOR: &str = r##""""Golden OCI configs from the Python builder for runtime/noded/tests/oci_golden.rs.

Run with the repository's Python: `.venv/bin/python golden.py <init binary>`.
Prints one JSON document: the fixture account files and, per case, the spec,
the image config, the node network mode, the namespace path, and either the
config (plus its exact `json.dumps(indent=2, sort_keys=True)` text) or the
error message.
"""
import json
import sys
import tempfile
from pathlib import Path

from ucloud_sandboxes.direct_oci import DirectOciConfigBuilder
from ucloud_sandboxes.image_rootfs import DockerImageConfig, MaterializedRootfs
from ucloud_sandboxes.sandbox import SandboxSpec

PASSWD = (
    "root:x:0:0:root:/root:/bin/bash\n"
    "daemon:x:1:1:daemon:/usr/sbin:/usr/sbin/nologin\n"
    "alice:x:1000:1000:Alice:/home/alice:/bin/sh\n"
    "bob:x:1001:1001::relative:\n"
    "short:x:7\n"
    "carol:x:0042:0042:Carol:/home/carol:/bin/zsh\r\n"
)
GROUP = "root:x:0:\nstaff:x:50:alice\nusers:x:100:\ndevs:x:2000:alice,bob\n"

IMAGES = {
    "full": {"Entrypoint": ["/usr/bin/env"], "Cmd": ["sh"], "Env": ["PATH=/usr/bin", "IMAGE_ONLY=yes"],
             "WorkingDir": "/image-work", "User": "123:456"},
    "empty": {},
    "alice": {"Cmd": ["python", "-c", "print(1)"], "User": "alice", "Env": ["LANG=C.UTF-8"]},
    "badenv": {"Cmd": ["true"], "Env": ["NOVALUE"]},
}
TEXT_CASES = {"default", "root_caps_groups", "linux_host"}
NETNS = "/run/netns/ucloud-0123456789abcdef0123"
BASE = {"image": "registry.example:5000/env:task@sha256:" + "c" * 64, "memory_mb": 512, "disk_mb": 1024}
CASES = [
    ("default", "full", "sandbox", NETNS, {"id": "s1", "command": ["echo", "hi"]}),
    ("image_defaults", "full", "sandbox", NETNS, {"id": "s2"}),
    ("root_caps_groups", "full", "sandbox", NETNS, {
        "id": "s3", "cpus": 1.5, "working_dir": "/srv", "env": {"PATH": "/custom", "Z": "é"},
        "labels": {"team": "rl", "a.b": "c"},
        "security": {"user": "0", "cap_drop": ["CHOWN", "cap_kill"], "cap_add": ["net_admin", "CAP_SYS_PTRACE"],
                     "supplementary_groups": ["staff", "2000", "50"], "pids_limit": None,
                     "read_only_rootfs": True, "no_new_privileges": False},
        "filesystem": {"workspace_storage": "tmpfs", "shm_mb": 128, "tmpfs_mb": 32, "run_tmpfs_mb": 8,
                       "management_helper": "static"}}),
    ("managed", "alice", "sandbox", NETNS, {
        "id": "s4", "parkable": True, "managed_process": True, "cpus": 0.125,
        "security": {"user": "alice:devs"}}),
    ("linux_host", "full", "none", None, {
        "id": "s5", "profile": "linux_host", "network": "none", "command": ["sleep", "1"],
        "linux_host": {"enable_cron": True, "writable_paths": ["/tmp", "/logs"]}}),
    ("linux_session_named", "alice", "sandbox", NETNS, {"id": "s6", "profile": "linux_session"}),
    ("linux_session_relative_home", "empty", "sandbox", NETNS, {
        "id": "s7", "profile": "linux_session", "security": {"user": "1001"}, "env": {"HOME": "/h"}}),
    ("linux_session_workspace_home", "empty", "sandbox", NETNS, {
        "id": "s7b", "profile": "linux_session", "security": {"user": "1001"},
        "filesystem": {"workspace_path": "/data/ws"}}),
    ("caps_all", "full", "sandbox", NETNS, {
        "id": "s8", "command": ["x"], "security": {"user": "4242", "cap_drop": ["ALL"], "cap_add": ["ALL"],
                                                   "init": False}}),
    ("numeric_with_group", "full", "sandbox", NETNS, {
        "id": "s9", "command": ["x"], "security": {"user": "1000:50"}}),
    ("leading_zero_uid", "full", "sandbox", NETNS, {
        "id": "s10", "command": ["x"], "security": {"user": "042:users"}}),
    ("image_user", "full", "sandbox", NETNS, {"id": "s11", "command": ["x"], "security": {"user": None}}),
    ("root_default", "empty", "sandbox", NETNS, {"id": "s12", "command": ["x"], "security": {"user": ""}}),
    ("cpu_half_even", "full", "sandbox", NETNS, {"id": "s13", "command": ["x"], "cpus": 0.000025}),
    ("cpu_tiny", "full", "sandbox", NETNS, {"id": "s14", "command": ["x"], "cpus": 0.000001}),
    ("legacy_quota", "full", "sandbox", NETNS, {
        "id": "s15", "command": ["x"], "filesystem": {"enforce_disk_quota": True}}),
    ("dns_and_policy", "full", "sandbox", NETNS, {
        "id": "s16", "command": ["x"], "dns_servers": ["9.9.9.9"], "network_policy": {"egress": "direct"}}),
    # Errors.
    ("unknown_user", "full", "sandbox", NETNS, {"id": "e1", "command": ["x"], "security": {"user": "nobody"}}),
    ("unknown_group", "full", "sandbox", NETNS, {"id": "e2", "command": ["x"], "security": {"user": "0:wheel"}}),
    ("unknown_supplementary", "full", "sandbox", NETNS, {
        "id": "e3", "command": ["x"], "security": {"supplementary_groups": ["wheel"]}}),
    ("bad_cap", "full", "sandbox", NETNS, {"id": "e4", "command": ["x"], "security": {"cap_add": ["CAP_FOO"]}}),
    ("cap_prefix_only", "full", "sandbox", NETNS, {"id": "e5", "command": ["x"], "security": {"cap_add": ["CAP_"]}}),
    ("ssh", "full", "sandbox", NETNS, {"id": "e6", "command": ["x"], "ssh": {"enabled": True}}),
    ("none_on_sandbox_node", "full", "sandbox", NETNS, {"id": "e7", "command": ["x"], "network": "none"}),
    ("netns_on_none_node", "full", "none", NETNS, {"id": "e8", "command": ["x"], "network": "none"}),
    ("relative_netns", "full", "sandbox", "relative/ns", {"id": "e9", "command": ["x"]}),
    ("no_process", "empty", "sandbox", NETNS, {"id": "e10"}),
    ("bad_image_env", "badenv", "sandbox", NETNS, {"id": "e11"}),
    ("no_memory", "full", "sandbox", NETNS, {"id": "e12", "command": ["x"], "memory_mb": None}),
    ("relative_cwd", "full", "sandbox", NETNS, {"id": "e13", "command": ["x"], "working_dir": "rel"}),
    ("uid_out_of_range", "full", "sandbox", NETNS, {"id": "e14", "command": ["x"], "security": {"user": "4294967295"}}),
    ("required_feature", "full", "sandbox", NETNS, {"id": "e15", "command": ["x"], "required_features": ["posix-acl"]}),
    ("reserved_workspace", "full", "sandbox", NETNS, {"id": "e16", "command": ["x"], "filesystem": {"workspace_path": "/run/x"}}),
    ("reserved_label", "full", "sandbox", NETNS, {"id": "e17", "command": ["x"], "labels": {"UCloud-Sandboxes.x": "y"}}),
]


def main():
    init = Path(sys.argv[1])
    out = {"passwd": PASSWD, "group": GROUP, "cases": []}
    with tempfile.TemporaryDirectory() as tmp:
        rootfs = Path(tmp) / "rootfs"
        (rootfs / "etc").mkdir(parents=True)
        (rootfs / "etc" / "passwd").write_text(PASSWD)
        (rootfs / "etc" / "group").write_text(GROUP)
        for name, image_name, mode, netns, spec_raw in CASES:
            raw = {**BASE, **spec_raw}
            raw = {key: value for key, value in raw.items() if value is not None or key != "memory_mb"}
            case = {"name": name, "spec": raw, "image_config": IMAGES[image_name], "network_mode": mode,
                    "netns": netns}
            try:
                spec = SandboxSpec.from_dict(raw)
                image = MaterializedRootfs(
                    image_ref=raw["image"], image_id="sha256:" + "a" * 64, rootfs_identity_sha256="b" * 64,
                    rootfs=rootfs, image_config=DockerImageConfig.from_inspection(IMAGES[image_name]))
                builder = DirectOciConfigBuilder(init_binary=init, managed_init_binary=init, network_mode=mode)
                config = builder.build(spec, image, network_namespace_path=Path(netns) if netns else None)
                case["config"] = config
                if name in TEXT_CASES:
                    case["config_text"] = json.dumps(config, indent=2, sort_keys=True) + "\n"
            except ValueError as exc:
                case["error"] = str(exc)
            out["cases"].append(case)
    json.dump(out, sys.stdout, indent=1, sort_keys=True)


if __name__ == "__main__":
    main()
"##;
